template <class T>
inline Span<T> simse_spanOf(List<T>* items) {
    return Span<T>(items->data(), items->size());
}

template <class T>
inline Span<T> simse_spanOf(Array<T>* items) {
    const Int count = items->count();
    return Span<T>(count > 0 ? &(*items)[0] : nullptr, count);
}

inline Span<Char> simse_spanOfStr(Str* text) {
    return Span<Char>{reinterpret_cast<Char*>(text->data()), text->size()};
}

inline Span<Char> simse_spanOfStr(Span<Char> view) {
    return view;
}

template <class T>
inline void simse_list_append(List<T>& self, const std::type_identity_t<T>& value) {
    self.push_back(value);
}

template <class T>
inline List<T> simse_listOf(const List<T>* values) {
    return *values;
}

template <class T>
inline void simse_list_removeAt(List<T>& self, Int index) {
    self.erase(self.begin() + index);
}

template <class T>
inline void simse_list_removeRange(List<T>& self, Int start, Int end) {
    self.erase(self.begin() + start, self.begin() + end);
}

template <class T>
inline Int simse_array_count(const Array<T>& self) {
    return self.count();
}


inline void simse_str_append(Str& self, Char value) {
    self.push_back(static_cast<char>(value));
}

inline void simse_str_appendStr(Str& self, const Str& value) {
    self.append(value);
}

inline void simse_str_plusAssign(Str& self, const Str& value) {
    self.append(value);
}

inline void simse_str_plusAssign(Str& self, Char value) {
    self.push_back(static_cast<char>(value));
}

template <class T>
inline void simse_list_plusAssign(List<T>& self, const std::type_identity_t<T>& value) {
    self.push_back(value);
}

inline void simse_str_appendStrPtr(Str& self, const Str* value) {
    if (value != nullptr) self.append(*value);
}

inline void simse_str_reserve(Str& self, Int count) {
    self.reserve((Str::size_type) count);
}

inline Int simse_lenOf(const Str& self) {
    return self.size();
}

template <class T, int N>
inline Int simse_lenOf(const SmallVector<T, N>& self) {
    return self.size();
}

inline Char simse_str_charAt(const Str& self, Int index) {
    return (Char) self[index];
}

inline Opt<Float64> simse_str_toFloat(const Str& self) {
    if (self.empty()) return Opt<Float64>();
    const char* begin = self.data();
    char* end = nullptr;
    errno = 0;
    const Float64 value = std::strtod(begin, &end);
    if (end != begin + self.size() || errno == ERANGE) return Opt<Float64>();
    Opt<Float64> result;
    result.setValue(value);
    return result;
}

inline void simse_str_initByValue(Str& self, const Str& value) {
    self = value;
}

template <class T>
inline Str simse_num_toString(const T& self) {
    return std::to_string(self);
}

inline Str simse_bool_toString(Bool self) {
    return self ? "true" : "false";
}

template <class K, class V>
inline Dictionary<K, V> simse_dictionaryOf() {
    return Dictionary<K, V>();
}

template <class K, class V>
inline V* simse_dict_getPtr(const Dictionary<K, V>& self, const std::type_identity_t<K>& key) {
    return self.valuePtr(key);
}

template <class K, class V>
inline Opt<V> simse_dict_get(const Dictionary<K, V>& self, const std::type_identity_t<K>& key) {
    const V* found = simse_dict_getPtr(self, key);
    if (found == nullptr) return Opt<V>();
    Opt<V> result;
    result.setValue(*found);
    return result;
}

template <class K, class V>
inline Bool simse_dict_has(const Dictionary<K, V>& self, const std::type_identity_t<K>& key) {
    return simse_dict_getPtr(self, key) != nullptr;
}

template <class K, class V>
inline void simse_dict_insert(Dictionary<K, V>& self, const std::type_identity_t<K>& key,
                              const std::type_identity_t<V>& value) {
    self.insert_or_assign(key, value);
}

template <class K, class V>
inline void simse_dict_remove(Dictionary<K, V>& self, const std::type_identity_t<K>& key) {
    self.erase(key);
}

template <class K, class V>
inline Int simse_dict_size(const Dictionary<K, V>& self) {
    return (Int) self.size();
}

template <class K, class V>
inline List<K> simse_dict_keys(const Dictionary<K, V>& self) {
    List<K> out;
    out.reserve((Int) self.size());
    for (const auto& entry : self) out.push_back(entry.first);
    return out;
}

template <class K, class V>
inline List<V> simse_dict_values(const Dictionary<K, V>& self) {
    List<V> out;
    out.reserve((Int) self.size());
    for (const auto& entry : self) out.push_back(entry.second);
    return out;
}

template <class K, class V>
inline void simse_dict_clear(Dictionary<K, V>& self) {
    self.clear();
}

template <class T>
inline Bool simse_list_contains(const List<T>& self, const std::type_identity_t<T>& value) {
    for (const T& item : self) {
        if (item == value) return true;
    }
    return false;
}

template <class T, class F>
inline void simse_list_sort(List<T>& self, F less) {
    Func<Bool(T*, T*)> fn = less;
    std::sort(self.begin(), self.end(), [&fn](const T& a, const T& b) {
        return fn(const_cast<T*>(&a), const_cast<T*>(&b));
    });
}

Str simse_native_readFile(const Str& path) {
    Str result;
    FILE* file = fopen(path.c_str(), "rb");
    if (file == nullptr) return result;
    fseek(file, 0, SEEK_END);
    const int fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);
    result.resize(fileSize);
    fread(result.data(), 1, fileSize, file);
    fclose(file);
    return result;
}

List<Str> simse_listFiles(const Str& dir, const Str& ext) {
    List<Str> matchingFiles;

    const std::string dirText = simse_toStdString(dir);
    const std::string wantedExt = simse_toStdString(ext);

    if (!std::filesystem::exists(dirText) || !std::filesystem::is_directory(dirText)) {
        return matchingFiles;
    }
    for (const auto& entry: std::filesystem::recursive_directory_iterator(dirText)) {
        if (entry.is_regular_file() && entry.path().extension() == wantedExt) {
            matchingFiles.push_back(simse_fromStdString(entry.path().generic_string()));
        }
    }
    std::sort(matchingFiles.begin(), matchingFiles.end());
    return matchingFiles;
}

List<Str> simse_listFilesDirect(const Str& dir, const Str& ext) {
    List<Str> files;
    std::error_code ec;
    if (!std::filesystem::is_directory(simse_toStdString(dir), ec)) {
        return files;
    }
    for (const auto& entry: std::filesystem::directory_iterator(simse_toStdString(dir), ec)) {
        if (entry.is_regular_file() && entry.path().extension() == simse_toStdString(ext)) {
            files.push_back(simse_fromStdString(entry.path().generic_string()));
        }
    }
    std::sort(files.begin(), files.end());
    return files;
}

Bool simse_writeFile(const Str& path, const Str& content) {
    FILE* out = fopen(path.c_str(), "wb");
    if (out == nullptr) {
        return false;
    }
    fwrite(content.data(), 1, content.length(), out);
    fclose(out);
    return true;
}

Bool simse_createDirectories(const Str& path) {
    std::error_code ec;
    std::filesystem::create_directories(simse_toStdString(path), ec);
    return !ec;
}

Str simse_pathCanonical(const Str& path) {
    std::error_code ec;
    std::filesystem::path canonical = std::filesystem::weakly_canonical(
            std::filesystem::path(simse_toStdString(path)), ec);
    return ec ? path : simse_fromStdString(canonical.string());
}

Bool simse_pathIsDirectory(const Str& path) {
    std::error_code ec;
    return std::filesystem::is_directory(simse_toStdString(path), ec);
}

Bool simse_pathExists(const Str& path) {
    std::error_code ec;
    return std::filesystem::exists(simse_toStdString(path), ec);
}

Bool simse_deleteFile(const Str& path) {
    std::error_code ec;
    std::filesystem::remove(simse_toStdString(path), ec);
    return !ec && !std::filesystem::exists(simse_toStdString(path), ec);
}

void simse_eprintln(const Str& text) {
    fprintf(stderr, "%s\n", text.c_str());
}

static Int simse_process_normalize(int status) {
#if defined(_WIN32)
    return (Int) status;
#else
    if (status == -1) return -1;
    if (WIFEXITED(status)) return (Int) WEXITSTATUS(status);
    if (WIFSIGNALED(status)) return (Int) (128 + WTERMSIG(status));
    return (Int) status;
#endif
}

Int simse_process_run(const Str& command) {
    const std::string cmd = simse_toStdString(command);
    return simse_process_normalize(std::system(cmd.c_str()));
}

Str simse_process_capture(const Str& command, Int* exitCode) {
    std::string cmd = simse_toStdString(command);
    cmd += " 2>&1";
#if defined(_WIN32)
    FILE* pipe = _popen(cmd.c_str(), "r");
#else
    FILE* pipe = popen(cmd.c_str(), "r");
#endif
    Str text;
    if (pipe == nullptr) {
        if (exitCode != nullptr) *exitCode = -1;
        return text;
    }
    char buffer[4096];
    std::size_t got = 0;
    while ((got = std::fread(buffer, 1, sizeof(buffer), pipe)) > 0) {
        text.append(buffer, (Int) got);
    }
#if defined(_WIN32)
    const int status = _pclose(pipe);
#else
    const int status = pclose(pipe);
#endif
    if (exitCode != nullptr) *exitCode = simse_process_normalize(status);
    return text;
}

template <class T>
inline void simse_strTableExpand(const T* stream, Int* out, Int count) {
    Int at = 0;
    Int cursor = 1; 
    while (at < count) {
        const Int literals = (Int) stream[cursor++];
        for (Int i = 0; i < literals && at < count; i++) out[at++] = (Int) stream[cursor++];
        if (at >= count) break;
        const Int runs = (Int) stream[cursor++];
        for (Int i = 0; i < runs && at < count; i++) {
            const Int times = (Int) stream[cursor++];
            const Int value = (Int) stream[cursor++];
            for (Int j = 0; j < times && at < count; j++) out[at++] = value;
        }
    }
}

inline void simse_strTableDecode(const char* pool, const Int* starts, const Int* lengths, Span<Char>* table, Int count) {
    Char* bytes = const_cast<Char*>(reinterpret_cast<const Char*>(pool));
    Int delta = 0;  
    Int length = 0; 
    Int at = 0;
    for (Int i = 0; i < count; i++) {
        delta -= starts[i];
        length -= lengths[i];
        at += delta;
        table[i] = Span<Char>{bytes + at, length};
    }
}

inline SmString::SmString(const Span<Char>& view)
    : SmString(reinterpret_cast<const char*>(view.ptr), view.len) {
}
